PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS communication_mobile_change_events(id INTEGER PRIMARY KEY AUTOINCREMENT,organization_id TEXT NOT NULL,collection_key TEXT NOT NULL,record_id TEXT NOT NULL,operation TEXT NOT NULL CHECK(operation IN('upsert','delete')),payload_json TEXT);
CREATE TRIGGER IF NOT EXISTS communication_mobile_change_apply AFTER INSERT ON communication_mobile_change_events BEGIN
 INSERT INTO mobile_sync_record_versions(organization_id,module_key,collection_key,record_id,version,deleted,server_updated_at,last_device_id) VALUES(NEW.organization_id,'communications',NEW.collection_key,NEW.record_id,1,CASE WHEN NEW.operation='delete' THEN 1 ELSE 0 END,CURRENT_TIMESTAMP,NULL) ON CONFLICT(organization_id,module_key,collection_key,record_id) DO UPDATE SET version=mobile_sync_record_versions.version+1,deleted=excluded.deleted,server_updated_at=CURRENT_TIMESTAMP,last_device_id=NULL;
 DELETE FROM mobile_sync_tombstones WHERE NEW.operation='upsert' AND organization_id=NEW.organization_id AND module_key='communications' AND collection_key=NEW.collection_key AND record_id=NEW.record_id;
 INSERT INTO mobile_sync_tombstones(organization_id,module_key,collection_key,record_id,version,deleted_at,device_id) SELECT NEW.organization_id,'communications',NEW.collection_key,NEW.record_id,v.version,CURRENT_TIMESTAMP,NULL FROM mobile_sync_record_versions v WHERE NEW.operation='delete' AND v.organization_id=NEW.organization_id AND v.module_key='communications' AND v.collection_key=NEW.collection_key AND v.record_id=NEW.record_id ON CONFLICT(organization_id,module_key,collection_key,record_id) DO UPDATE SET version=excluded.version,deleted_at=CURRENT_TIMESTAMP,device_id=NULL;
 INSERT INTO mobile_sync_changes(organization_id,module_key,collection_key,record_id,version,operation,payload_json,changed_by,device_id,changed_at) SELECT NEW.organization_id,'communications',NEW.collection_key,NEW.record_id,v.version,NEW.operation,NEW.payload_json,NULL,NULL,CURRENT_TIMESTAMP FROM mobile_sync_record_versions v WHERE v.organization_id=NEW.organization_id AND v.module_key='communications' AND v.collection_key=NEW.collection_key AND v.record_id=NEW.record_id;
 DELETE FROM communication_mobile_change_events WHERE id=NEW.id;
END;
CREATE TRIGGER IF NOT EXISTS comm_sync_type_i AFTER INSERT ON communication_message_types BEGIN INSERT INTO communication_mobile_change_events VALUES(NULL,NEW.organization_id,'message-types',NEW.id,'upsert',json_object('id',NEW.id,'typeKey',NEW.type_key,'name',NEW.name,'moduleKey',NEW.module_key,'category',NEW.category,'audienceKind',NEW.audience_kind,'subjectTemplate',NEW.subject_template,'messageTemplate',NEW.message_template,'audienceDefaults',json(NEW.audience_defaults_json),'systemType',NEW.system_type,'active',NEW.active)); END;
CREATE TRIGGER IF NOT EXISTS comm_sync_type_u AFTER UPDATE ON communication_message_types BEGIN INSERT INTO communication_mobile_change_events VALUES(NULL,NEW.organization_id,'message-types',NEW.id,CASE WHEN NEW.active=1 THEN 'upsert' ELSE 'delete' END,CASE WHEN NEW.active=1 THEN json_object('id',NEW.id,'typeKey',NEW.type_key,'name',NEW.name,'moduleKey',NEW.module_key,'category',NEW.category,'audienceKind',NEW.audience_kind,'subjectTemplate',NEW.subject_template,'messageTemplate',NEW.message_template,'audienceDefaults',json(NEW.audience_defaults_json),'systemType',NEW.system_type,'active',NEW.active) ELSE NULL END); END;
CREATE TRIGGER IF NOT EXISTS comm_sync_type_d AFTER DELETE ON communication_message_types BEGIN INSERT INTO communication_mobile_change_events VALUES(NULL,OLD.organization_id,'message-types',OLD.id,'delete',NULL); END;
CREATE TRIGGER IF NOT EXISTS comm_sync_campaign_i AFTER INSERT ON communication_campaigns BEGIN INSERT INTO communication_mobile_change_events VALUES(NULL,NEW.organization_id,'campaigns',NEW.id,'upsert',json_object('id',NEW.id,'messageTypeId',NEW.message_type_id,'typeKey',NEW.type_key,'moduleKey',NEW.module_key,'name',NEW.name,'senderName',NEW.sender_name,'subjectTemplate',NEW.subject_template,'messageTemplate',NEW.message_template,'channels',json(NEW.channels_json),'audienceKind',NEW.audience_kind,'audience',json(NEW.audience_json),'status',NEW.status,'scheduledAt',NEW.scheduled_at,'startedAt',NEW.started_at,'completedAt',NEW.completed_at,'recipientCount',NEW.recipient_count,'skippedCount',NEW.skipped_count,'deliveryCount',NEW.delivery_count,'sentCount',NEW.sent_count,'failedCount',NEW.failed_count)); END;
CREATE TRIGGER IF NOT EXISTS comm_sync_campaign_u AFTER UPDATE ON communication_campaigns BEGIN INSERT INTO communication_mobile_change_events VALUES(NULL,NEW.organization_id,'campaigns',NEW.id,'upsert',json_object('id',NEW.id,'messageTypeId',NEW.message_type_id,'typeKey',NEW.type_key,'moduleKey',NEW.module_key,'name',NEW.name,'senderName',NEW.sender_name,'subjectTemplate',NEW.subject_template,'messageTemplate',NEW.message_template,'channels',json(NEW.channels_json),'audienceKind',NEW.audience_kind,'audience',json(NEW.audience_json),'status',NEW.status,'scheduledAt',NEW.scheduled_at,'startedAt',NEW.started_at,'completedAt',NEW.completed_at,'recipientCount',NEW.recipient_count,'skippedCount',NEW.skipped_count,'deliveryCount',NEW.delivery_count,'sentCount',NEW.sent_count,'failedCount',NEW.failed_count)); END;
CREATE TRIGGER IF NOT EXISTS comm_sync_campaign_d AFTER DELETE ON communication_campaigns BEGIN INSERT INTO communication_mobile_change_events VALUES(NULL,OLD.organization_id,'campaigns',OLD.id,'delete',NULL); END;
CREATE TRIGGER IF NOT EXISTS comm_sync_recipient_i AFTER INSERT ON communication_recipients BEGIN INSERT INTO communication_mobile_change_events VALUES(NULL,NEW.organization_id,'recipients',NEW.id,'upsert',json_object('id',NEW.id,'campaignId',NEW.campaign_id,'recipientType',NEW.recipient_type,'recipientId',NEW.recipient_id,'relatedEntityType',NEW.related_entity_type,'relatedEntityId',NEW.related_entity_id,'recipientName',NEW.recipient_name,'phone',NEW.phone,'data',json(NEW.data_json),'status',NEW.status,'skipReason',NEW.skip_reason,'createdAt',NEW.created_at)); END;
CREATE TRIGGER IF NOT EXISTS comm_sync_recipient_u AFTER UPDATE ON communication_recipients BEGIN INSERT INTO communication_mobile_change_events VALUES(NULL,NEW.organization_id,'recipients',NEW.id,'upsert',json_object('id',NEW.id,'campaignId',NEW.campaign_id,'recipientType',NEW.recipient_type,'recipientId',NEW.recipient_id,'relatedEntityType',NEW.related_entity_type,'relatedEntityId',NEW.related_entity_id,'recipientName',NEW.recipient_name,'phone',NEW.phone,'data',json(NEW.data_json),'status',NEW.status,'skipReason',NEW.skip_reason,'createdAt',NEW.created_at)); END;
CREATE TRIGGER IF NOT EXISTS comm_sync_recipient_d AFTER DELETE ON communication_recipients BEGIN INSERT INTO communication_mobile_change_events VALUES(NULL,OLD.organization_id,'recipients',OLD.id,'delete',NULL); END;
CREATE TRIGGER IF NOT EXISTS comm_sync_delivery_i AFTER INSERT ON communication_deliveries BEGIN INSERT INTO communication_mobile_change_events VALUES(NULL,NEW.organization_id,'deliveries',NEW.id,'upsert',json_object('id',NEW.id,'campaignId',NEW.campaign_id,'recipientSnapshotId',NEW.recipient_snapshot_id,'channel',NEW.channel,'recipientPhone',NEW.recipient_phone,'provider',NEW.provider,'renderedSubject',NEW.rendered_subject,'renderedMessage',NEW.rendered_message,'status',NEW.status,'attempts',NEW.attempts,'providerMessageId',NEW.provider_message_id,'lastError',NEW.last_error,'queuedAt',NEW.queued_at,'sentAt',NEW.sent_at,'deliveredAt',NEW.delivered_at,'failedAt',NEW.failed_at)); END;
CREATE TRIGGER IF NOT EXISTS comm_sync_delivery_u AFTER UPDATE ON communication_deliveries BEGIN INSERT INTO communication_mobile_change_events VALUES(NULL,NEW.organization_id,'deliveries',NEW.id,'upsert',json_object('id',NEW.id,'campaignId',NEW.campaign_id,'recipientSnapshotId',NEW.recipient_snapshot_id,'channel',NEW.channel,'recipientPhone',NEW.recipient_phone,'provider',NEW.provider,'renderedSubject',NEW.rendered_subject,'renderedMessage',NEW.rendered_message,'status',NEW.status,'attempts',NEW.attempts,'providerMessageId',NEW.provider_message_id,'lastError',NEW.last_error,'queuedAt',NEW.queued_at,'sentAt',NEW.sent_at,'deliveredAt',NEW.delivered_at,'failedAt',NEW.failed_at)); END;
CREATE TRIGGER IF NOT EXISTS comm_sync_delivery_d AFTER DELETE ON communication_deliveries BEGIN INSERT INTO communication_mobile_change_events VALUES(NULL,OLD.organization_id,'deliveries',OLD.id,'delete',NULL); END;
